# name: singleton_set_yes_rate
# description: Yes rate on sets with exactly one example, for targets other than that example; observed above null means the model under-generalizes from a single example (size principle too sharp), below null means it over-generalizes.
def test_statistic(df):
    ex = df["number_set"].astype(str).str.split(",", expand=True).apply(pd.to_numeric, errors="coerce").to_numpy(dtype=float)
    n = np.sum(~np.isnan(ex), axis=1)
    t = df["target"].astype(float).to_numpy()
    m = (n == 1) & (ex[:, 0] != t)
    if m.sum() == 0:
        return 0.0
    return float(df["rating"].to_numpy()[m].mean())

# name: cell_response_extremity
# description: Mean over (set, target) cells of |cell yes rate - 0.5|; observed below null means the model's predictions are over-confident (too close to 0/1, lacking a lapse/noise component), above null means people are more deterministic than the model.
def test_statistic(df):
    key = df["number_set"].astype(str) + "|" + df["target"].astype(str)
    cm = df["rating"].astype(float).groupby(key).mean()
    return float(np.abs(cm.to_numpy() - 0.5).mean())

# name: trial_index_yes_correlation
# description: Pearson correlation between trial_index and the yes response; observed more negative than null means people say "yes" less as the session goes on (a drift the stationary model does not produce), more positive means the reverse.
def test_statistic(df):
    x = df["trial_index"].to_numpy(dtype=float)
    y = df["rating"].to_numpy(dtype=float)
    if x.std() == 0 or y.std() == 0:
        return 0.0
    return float(np.corrcoef(x, y)[0, 1])
